userDefinedCss:
/* Glass: plain black panels, white-alpha rows, Inter/Roboto.
   Source: ~/.config/firefox/vimium-c.json */

/* #ui */

/* command HUD: a small black pill */
.HUD, .HUD.D { color: rgba(255, 255, 255, .75) !important; font: 12px/16px "Inter", "Roboto", "Noto Sans", sans-serif !important; }
.HUD::after, .HUD.D::after {
  background: rgba(12, 12, 12, .95) !important;
  border: 1px solid rgba(255, 255, 255, .14) !important;
  border-radius: 10px !important;
}

/* link hints */
.LH, .D > .LH {
  background: rgba(12, 12, 12, .95) !important;
  color: #fff !important;
  border: 1px solid rgba(255, 255, 255, .22) !important;
  border-radius: 6px !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, .5) !important;
  padding: 1px 5px !important;
  font: 600 11px/14px "Inter", "Roboto", "Noto Sans", sans-serif !important;
}
.MH, .D > .LH .MH { color: rgba(255, 255, 255, .4) !important; }
.LH.active, .D > .LH.active { background: #fff !important; color: #000 !important; }
.IH { background: rgba(255, 255, 255, .10) !important; border-color: rgba(255, 255, 255, .5) !important; }
.Flash { box-shadow: 0 0 0 2px rgba(255, 255, 255, .8) !important; }

/* #omni */

/* Compact. The frame height comes from vomnibarOptions.sizes
   ("bar,extra,row,widthRatio,maxWidth"): keep #bar = 42rem, rows = 34rem
   and list padding = 6rem in step with it, or the list gets clipped.
   The box-shadow has to fit the body margins (9/12/10rem) or it clips square. */
html, body { background: transparent !important; }
body {
  background: rgba(12, 12, 12, .96) !important;
  border-radius: 14rem !important;
  box-shadow: 0 3rem 9rem rgba(0, 0, 0, .55) !important;
  font-family: "Inter", "Roboto", "Noto Sans", sans-serif !important;
}
body::after { content: "" !important; border: 1rem solid rgba(255, 255, 255, .14) !important; border-radius: 14rem !important; }
#bar, #bar.empty, .has-dark > #bar {
  background: transparent !important;
  border: none !important;
  height: 30rem !important;
  padding: 6rem !important;
}
#input {
  height: 30rem !important;
  background: rgba(255, 255, 255, .08) !important;
  border: 1rem solid transparent !important;
  border-radius: 9rem !important;
  box-shadow: none !important;
  color: #fff !important;
  caret-color: #fff !important;
  font: 14rem/20rem "Inter", "Roboto", "Noto Sans", sans-serif !important;
  padding: 3rem 10rem !important;
}
#input:focus { background: rgba(255, 255, 255, .11) !important; border-color: rgba(255, 255, 255, .22) !important; }
#toolbar { color: rgba(255, 255, 255, .4) !important; top: 11rem !important; right: 8rem !important; }
#list { background: transparent !important; padding: 0 6rem 6rem !important; }
.item, .item.b {
  height: 34rem !important;
  padding: 2rem 10rem 0 !important;
  border: none !important;
  border-radius: 8rem !important;
}
.item:hover { background: rgba(255, 255, 255, .07) !important; }
.item.s, .p { background: rgba(255, 255, 255, .13) !important; }
.top {
  height: 17rem !important;
  color: rgba(255, 255, 255, .9) !important;
  font: 13rem/17rem "Inter", "Roboto", "Noto Sans", sans-serif !important;
}
.bottom { height: 14rem !important; line-height: 14rem !important; margin-left: 20rem !important; }
.icon, .tab, .math { --vc-c: rgba(255, 255, 255, .5); margin-top: 0.5rem !important; }
a, .mono-url a { color: rgba(255, 255, 255, .45) !important; font: 11rem/14rem "Inter", "Roboto", "Noto Sans", sans-serif !important; }
.label, .time { color: rgba(255, 255, 255, .4) !important; font-size: 11rem !important; }
match { color: #fff !important; font-weight: 700 !important; }
.title > match { text-decoration: none !important; }

/* #find */

#bar, .r, .r.D {
  background: rgba(12, 12, 12, .95) !important;
  color: #fff !important;
  border-radius: 10px 10px 0 0 !important;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .14) !important;
}
* { font-family: "Inter", "Roboto", "Noto Sans", sans-serif !important; }
#s::after, #c::after { color: rgba(255, 255, 255, .6) !important; }

/* #find:host */

:host { caret-color: #fff; }

/* #find:selection */

::selection { background: rgba(255, 255, 255, .3); color: #fff; }
